{
  "version": 2,
  "model": {
    "api": "chat-completions",
    "name": "fixture-model",
    "baseUrl": "https://model.example/v1",
    "keyEnv": "AGENTRY_MODEL_KEY"
  },
  "system": "You are the conformance fixture. Read the inputs, write one report.\n\nYour final message MUST be a single JSON document matching this JSON Schema, with no surrounding prose:\n\n{\"type\":\"object\",\"required\":[\"summary\"],\"properties\":{\"summary\":{\"type\":\"string\"}}}\n",
  "gateway": {
    "url": "http://gateway:8811/mcp",
    "tokenEnv": "MCP_GATEWAY_TOKEN"
  },
  "sessionDir": "/session",
  "results": {
    "maxBytes": 32768
  },
  "scrub": {
    "unchanged": [
      "read_input",
      "search_inputs"
    ]
  },
  "loop": {
    "repeats": 5,
    "cycleRepeats": 3,
    "maxPeriod": 4
  },
  "lengthRecoveries": 2,
  "coldClear": {
    "afterSeconds": 3600,
    "keepTurns": 2,
    "keepBrowser": 2,
    "minBytes": 4096
  },
  "compaction": {
    "threshold": 0.7,
    "checkpoint": "Keep, under these headings: the task, in the words the person used; the checklist, every step with its status, copied from the latest checklist result above; done, in progress, and blocked with why; the next step; the files, paths and identifiers in play; the constraints the task set and the approaches that failed.",
    "notes": "checklist.md in your scratch folder, which the checklist tool reads"
  },
  "retry": {
    "attempts": 3,
    "baseSeconds": 2,
    "maxSeconds": 60,
    "idleSeconds": 1800
  }
}
